#!/usr/bin/env bash
# test-bootstrap.sh: end-to-end tests of the bootstrap scripts.
#
# No network, no sleeps, no wall clock: gh is a stub on PATH (tests/stubs)
# that logs its argv and keeps GitHub's state in a JSON file, and the git
# remotes are local bare repos reached through BOOTSTRAP_GIT_BASE. The
# starter trees are copied in by the real copy-starter.sh, "merged" by moving
# the bare repo's main, and regenerated by the real regenerate.sh, which runs
# the exported repos' own generators on them. apply-settings.sh and
# install-machine.sh run against a second invented owner whose repos hold a
# fake engine and fake installers that log what they were asked to do.
# Everything happens under one temp dir, removed at the end, with a scratch
# HOME and GIT_CONFIG_GLOBAL.
#
# Run: bash tests/test-bootstrap.sh
# Exit 0 and "N assertions passed" mean it worked; each failed assertion
# prints FAIL and the exit code is 1.

set -uo pipefail
export PYTHONDONTWRITEBYTECODE=1   # no __pycache__ in a tree that copy-starter.sh may copy
B=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
K=$(cd "$B/.." && pwd)
T=$(mktemp -d "${TMPDIR:-/tmp}/bootstrap-test.XXXXXX")
trap 'rm -rf "$T"' EXIT
PASSES=0 FAILS=0
ok()   { PASSES=$((PASSES + 1)); }
bad()  { FAILS=$((FAILS + 1)); printf 'FAIL: %s\n' "$*"; }
assert()      { local d=$1; shift; if "$@" >/dev/null 2>&1; then ok; else bad "$d"; fi; }
assert_not()  { local d=$1; shift; if "$@" >/dev/null 2>&1; then bad "$d"; else ok; fi; }
assert_eq()   { if [ "$2" = "$3" ]; then ok; else bad "$1: expected [$3], got [$2]"; fi; }
has()         { grep -qF -- "$2" "$1"; }       # file contains text
writes()      { python3 -I -c '
import json, sys
n = 0
for line in open(sys.argv[1], encoding="utf-8"):
    a = json.loads(line)
    if a[0] == "api":
        m = a[a.index("-X") + 1] if "-X" in a else "GET"
        n += m != "GET"
    elif a[:2] in (["repo", "create"], ["variable", "set"], ["secret", "set"], ["pr", "create"]):
        n += 1
print(n)' "$1"; }
log_lines()   { wc -l < "$1" | tr -d ' '; }
since()       { tail -n +"$(($1 + 1))" "$GH_LOG" > "$T/delta"; writes "$T/delta"; }   # write calls after line N
jqs()         { jq -r "$1" "$GH_STUB_STATE"; }
jqset()       { jq "$1" "$GH_STUB_STATE" > "$T/s" && mv "$T/s" "$GH_STUB_STATE"; }

export PATH="$B/tests/stubs:$PATH"
export TMPDIR="$T/tmp" HOME="$T/home"; mkdir -p "$TMPDIR" "$HOME"
export GH_LOG="$T/gh.log" GH_STUB_STATE="$T/gh-state.json"
export GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL="$T/gitconfig"
export BOOTSTRAP_GIT_BASE="file://$T/remotes"
export GIT_AUTHOR_DATE=2026-01-01T00:00:00Z GIT_COMMITTER_DATE=2026-01-01T00:00:00Z
unset GH_TOKEN GITHUB_TOKEN CLAUDE_CONFIG_DIR ADOPT_STATE_FILE XDG_STATE_HOME GH_STUB_GIT_REMOTES
touch "$GH_LOG"
git config --global user.name "Test User"
git config --global user.email "test-user@example.com"
git config --global init.defaultBranch main
git config --global protocol.file.allow always

SCRIPTS=(create-repos.sh create-environments.sh create-apps.sh set-secrets.sh copy-starter.sh
         regenerate.sh apply-settings.sh install-machine.sh verify.sh status.sh)
FLEET=(_agent-guidance repo-settings acsi-agentskills acsi-agentskills-private skills-evals wsl-automation)
O=acme-example
OUT="$T/out" ERR="$T/err"
run() { "$@" >"$OUT" 2>"$ERR"; }   # run a script, keep its stdout and stderr
cd "$K" || exit 1

# Unique values that must never leave the stubs' memory.
PEM_MARK="PEMBODY$(od -An -N8 -tx1 /dev/urandom | tr -d ' \n')"
CS_MARK="CLIENTSECRET$(od -An -N8 -tx1 /dev/urandom | tr -d ' \n')"
BEARER="bearer-$(od -An -N12 -tx1 /dev/urandom | tr -d ' \n')"
export GH_STUB_FAKE_PEM=$'-----BEGIN FAKE KEY-----\n'"$PEM_MARK"$'\n-----END FAKE KEY-----\n'
export GH_STUB_CLIENT_SECRET="$CS_MARK"
sha() { printf '%s' "$1" | sha256sum | cut -d' ' -f1; }
uid_of() { python3 -I -c 'import sys; print(5000 + sum(map(ord, sys.argv[1])))' "$1"; }   # the gh stub's user ids

new_config() { # path plan [owner]
  cat > "$1" <<EOF
# test config
OWNER=${3:-$O}
OWNER_TWO=${3:-$O}-two
OWNER_TYPE=user
PLAN=$2
OWNER_NAME=Acme Example
REPOS_DIR=$T/home/repos
EOF
}
CFG="$T/fleet.env"; new_config "$CFG" free

# ======================================================== syntax and lint
for s in "${SCRIPTS[@]}" lib/common.sh lib/pr.sh tests/stubs/gh; do
  assert "bash -n $s" bash -n "$B/$s"
done
if command -v shellcheck >/dev/null 2>&1; then
  for s in "${SCRIPTS[@]}"; do assert "shellcheck $s" shellcheck -x -S warning "$B/$s"; done
else
  echo "note: shellcheck not installed; skipped"
fi
for s in "${SCRIPTS[@]}"; do
  assert "$s has a usage header" grep -q "^# $s" "$B/$s"
  assert "$s uses set -euo pipefail" grep -qx 'set -euo pipefail' "$B/$s"
  assert "$s --help prints its usage" bash -c '"$1" "$2" --help | grep -qF "$3"' _ bash "$B/$s" "$s ["
done
for p in lib/substitute.py render-quickstart.py tests/check-refs.py tests/check-steps.py tests/check-links.py \
         tests/check-guide-lists.py tests/check-branch-prefixes.py tests/check-one-owner.py tests/mdlinks.py tests/stubs/gh_stub.py; do
  assert "$p parses" python3 -I -c 'import ast, sys; ast.parse(open(sys.argv[1], encoding="utf-8").read())' "$B/$p"
done
# The bash >= 4.4 guard: the version test, and that a too-old bash stops before anything runs.
guard() { bash -c '. "$1"; bash_version_ok "$2" "$3"' _ "$B/lib/common.sh" "$1" "$2"; }
assert "bash 4.4 passes the version guard" guard 4 4
assert "bash 5.0 passes the version guard" guard 5 0
assert_not "bash 4.3 fails the version guard" guard 4 3
assert_not "bash 3.2 fails the version guard" guard 3 2
sed 's/bash_version_ok "${BASH_VERSINFO\[0\]}" "${BASH_VERSINFO\[1\]}"/bash_version_ok 3 2/' "$B/lib/common.sh" > "$T/old-bash-common.sh"
assert_not "the guard's call site was found to rewrite" cmp -s "$B/lib/common.sh" "$T/old-bash-common.sh"
bash -c '. "$1"; echo reached' _ "$T/old-bash-common.sh" >"$OUT" 2>"$ERR"; rc=$?
assert_eq "a too-old bash exits 1 when common.sh is sourced" "$rc" 1
assert_not "nothing after the guard runs" has "$OUT" reached
assert "the refusal names the version needed" has "$ERR" "needs bash 4.4 or later"
# No script keeps a write helper in a pipeline, where its count and its die would be lost in a subshell.
assert_not "no script pipes into set_value or run_write_stdin" grep -nE '\|[[:space:]]*(set_value|run_write_stdin)\b' \
  "${SCRIPTS[@]/#/$B/}" "$B/lib/common.sh" "$B/lib/pr.sh"

# ======================================================== config parsing
printf 'OWNER=acme-example\nPLAN=free\nTOKEN=x\n' > "$T/bad1.env"
assert_not "an unknown config key is refused" bash "$B/create-repos.sh" --config "$T/bad1.env" --dry-run
printf 'OWNER=$(touch %s/pwned)\nPLAN=free\n' "$T" > "$T/bad2.env"
assert_not "a shell expression as OWNER is refused" bash "$B/create-repos.sh" --config "$T/bad2.env" --dry-run
assert_not "the config is never sourced" test -e "$T/pwned"
printf 'OWNER=acme-example\nPLAN=cheap\n' > "$T/bad3.env"
assert_not "an invalid PLAN is refused" bash "$B/create-repos.sh" --config "$T/bad3.env" --dry-run
printf 'OWNER=acme-example\nPLAN=free\nGUIDANCE_SYNC_APP_ID=12x\n' > "$T/bad4.env"
assert_not "a non-numeric App id is refused" bash "$B/create-repos.sh" --config "$T/bad4.env" --dry-run
printf 'OWNER=acme-example\nPLAN=free\nANTHROPIC_WORKSPACE_ID=svac_EXAMPLE0000000001\n' > "$T/bad5.env"
assert_not "a federation id of the wrong shape is refused" bash "$B/create-repos.sh" --config "$T/bad5.env" --dry-run
assert_not "a missing config is refused" bash "$B/create-repos.sh" --config "$T/none.env" --dry-run
assert_not "an unknown repo name is refused" bash "$B/create-repos.sh" --config "$CFG" --dry-run agent-skills

# ======================================================== create-repos.sh
run bash "$B/create-repos.sh" --config "$CFG" --dry-run; rc=$?
assert_eq "create-repos dry run exits 0" "$rc" 0
assert_eq "create-repos dry run makes no write calls" "$(writes "$GH_LOG")" 0
assert "dry run prints the results branch's tree, commit and ref" bash -c 'for u in git/trees git/commits git/refs; do grep -qF "DRY-RUN: gh api -X POST repos/acme-example/skills-evals/$u" "$1" || exit 1; done' _ "$OUT"
assert "dry run says it would create the orphan results branch" has "$OUT" "would have: created the orphan branch persistent/eval-results in acme-example/skills-evals"
assert_eq "dry run creates no branch" "$(jqs '[.repos[]? | .branches // {} | keys[]] | length')" 0
assert "create-repos dry run prints the private repo create call" has "$OUT" "DRY-RUN: gh repo create acme-example/acsi-agentskills-private --private"
assert "create-repos dry run says nothing was written" has "$OUT" "nothing was written"

run bash "$B/create-repos.sh" --config "$CFG"; rc=$?
assert_eq "create-repos exits 0" "$rc" 0
assert_eq "it creates exactly the six repos" "$(jqs '[.repos | keys[]] | sort | join(" ")')" \
  "acme-example/_agent-guidance acme-example/acsi-agentskills acme-example/acsi-agentskills-private acme-example/repo-settings acme-example/skills-evals acme-example/wsl-automation"
for r in _agent-guidance acsi-agentskills skills-evals wsl-automation; do
  assert_eq "free: $r is public" "$(jqs ".repos[\"$O/$r\"].visibility")" public
done
for r in acsi-agentskills-private repo-settings; do
  assert_eq "free: $r is private" "$(jqs ".repos[\"$O/$r\"].visibility")" private
done
assert_eq "every repo has a first commit" "$(jqs '[.repos[] | select(.has_commits)] | length')" 6
assert_eq "every README is the generated one, ending in the marker" \
  "$(jqs '[.repos[] | select(. as $r | ($r.readme // "") | startswith("# " + $r.name + "\n") and endswith("copy-starter.sh replaces this file while it is unchanged -->\n"))] | length')" 6
# skills-evals alone gets persistent/eval-results, as an orphan commit (no parent) holding a README.
assert_eq "persistent/eval-results exists on skills-evals only" "$(jqs '[.repos | to_entries[] | select(.value.branches["persistent/eval-results"] != null) | .key] | join(" ")')" "$O/skills-evals"
assert_eq "the results branch is an orphan commit" "$(jqs '.repos["acme-example/skills-evals"] | .commits[.branches["persistent/eval-results"]].parents | length')" 0
assert_eq "the results branch holds a README and nothing else" "$(jqs '.repos["acme-example/skills-evals"] | .trees[.commits[.branches["persistent/eval-results"]].tree] | map(.path) | join(",")')" README.md
assert "the results README says what the branch holds" jq -e '.repos["acme-example/skills-evals"] | .trees[.commits[.branches["persistent/eval-results"]].tree][0].content | contains("never merges into main")' "$GH_STUB_STATE"
assert_eq "labels agent-ready and on-hold on all six" "$(jqs '[.repos[] | select([.labels[].name] | index("agent-ready") and index("on-hold"))] | length')" 6
assert_eq "it leaves merge and Actions settings to fleet.yml" "$(jqs '[.repos[] | select(.allow_squash_merge and (.actions.sha_pinning_required | not))] | length')" 6
n=$(log_lines "$GH_LOG")
run bash "$B/create-repos.sh" --config "$CFG"; rc=$?
assert_eq "create-repos second run exits 0" "$rc" 0
assert_eq "create-repos second run makes no write calls" "$(since "$n")" 0
assert "create-repos second run says nothing to change" has "$OUT" "Nothing to change"
assert "create-repos second run sees the results branch" has "$OUT" "ok: acme-example/skills-evals has the persistent/eval-results branch"
# The branch gone (say, a new account that never ran this step): a dry run
# reports it and writes nothing; a real run makes it again, in three writes.
jqset 'del(.repos["acme-example/skills-evals"].branches["persistent/eval-results"])'
n=$(log_lines "$GH_LOG")
run bash "$B/create-repos.sh" --config "$CFG" --dry-run skills-evals; rc=$?
assert_eq "a dry run with the results branch missing exits 0" "$rc" 0
assert_eq "a dry run with the results branch missing writes nothing" "$(since "$n")" 0
assert "a dry run with the results branch missing would create it" has "$OUT" "would have: created the orphan branch persistent/eval-results"
n=$(log_lines "$GH_LOG")
run bash "$B/create-repos.sh" --config "$CFG" skills-evals; rc=$?
assert_eq "create-repos recreates a missing results branch" "$rc" 0
assert_eq "recreating the results branch is three writes (tree, commit, ref)" "$(since "$n")" 3
assert_eq "the recreated results branch exists" "$(jqs '.repos["acme-example/skills-evals"].branches["persistent/eval-results"] != null')" true
run bash "$B/create-repos.sh" --config "$CFG" --with-optional
assert_eq "--with-optional adds the private waiting-feed" "$(jqs '.repos["acme-example/waiting-feed"].visibility')" private
jqset 'del(.repos["acme-example/waiting-feed"])'
# A visibility mismatch is reported and not changed.
jqset '.repos["acme-example/repo-settings"].visibility = "public" | .repos["acme-example/repo-settings"].private = false'
run bash "$B/create-repos.sh" --config "$CFG" repo-settings; rc=$?
assert_eq "a visibility mismatch fails the run" "$rc" 1
assert "a visibility mismatch is named" has "$ERR" "repo-settings exists but is public"
assert_eq "a visibility mismatch is not changed" "$(jqs '.repos["acme-example/repo-settings"].visibility')" public
jqset '.repos["acme-example/repo-settings"].visibility = "private" | .repos["acme-example/repo-settings"].private = true'

# ======================================================== create-environments.sh
run bash "$B/create-environments.sh" --config "$CFG"; rc=$?
assert_eq "create-environments (free) exits 0" "$rc" 0
assert "free: fleet-apply in the private repo-settings is skipped, pointing at apply-settings.sh" has "$OUT" "apply fleet.yml from your machine with apply-settings.sh"
assert_eq "plugin-runtime-review has no branch policy" "$(jqs '.envs["acme-example/acsi-agentskills"]["plugin-runtime-review"].deployment_branch_policy')" null
assert_eq "plugin-runtime-review requires the owner" "$(jqs '.envs["acme-example/acsi-agentskills"]["plugin-runtime-review"].protection_rules[0].reviewers[0].reviewer.id')" "$(uid_of "$O")"
assert_eq "routine-fire has no reviewer" "$(jqs '.envs["acme-example/skills-evals"]["routine-fire"].protection_rules | length')" 0
assert_eq "routine-fire deploys only from main" "$(jqs '[.envs["acme-example/skills-evals"]["routine-fire"].policies[].name] | join(",")')" main
assert "the variables wait for the App ids" has "$OUT" "GUIDANCE_SYNC_APP_ID is empty in fleet.env"
assert "the federation ids are skipped as optional" has "$OUT" "ANTHROPIC_WORKSPACE_ID is empty in fleet.env (optional; docs/evals-and-loop.md#workload-identity-federation)"

CFGP="$T/fleet-paid.env"; new_config "$CFGP" paid
export GH_STUB_PLAN=paid
run bash "$B/create-environments.sh" --config "$CFGP"; rc=$?
assert_eq "create-environments (paid) exits 0" "$rc" 0
assert_eq "paid: fleet-apply exists with the owner as reviewer and main only" \
  "$(jqs '.envs["acme-example/repo-settings"]["fleet-apply"] | [(.protection_rules | length), ([.policies[].name] | join(","))] | map(tostring) | join(" ")')" "1 main"
n=$(log_lines "$GH_LOG")
run bash "$B/create-environments.sh" --config "$CFGP"; rc=$?
assert_eq "create-environments second run makes no write calls" "$(since "$n")" 0
assert "create-environments second run says nothing to change" has "$OUT" "Nothing to change"
jqset '.envs["acme-example/skills-evals"]["routine-fire"].policies += [{"id": 1, "name": "feature/*", "type": "branch"}]'
run bash "$B/create-environments.sh" --config "$CFGP"; rc=$?
assert_eq "an extra branch policy fails the run" "$rc" 1
assert "an extra branch policy is named, not deleted" has "$ERR" "also allows: branch/feature/*"
jqset '.envs["acme-example/skills-evals"]["routine-fire"].policies |= map(select(.name == "main"))'

# ======================================================== create-apps.sh
APPS=(guidance-sync settings-admin settings-read eval-improve roster registry-read)
n=$(log_lines "$GH_LOG")
run bash "$B/create-apps.sh" --config "$CFGP" --dry-run --out "$T/manifests"; rc=$?
assert_eq "create-apps dry run exits 0" "$rc" 0
assert_eq "create-apps dry run makes no write calls" "$(since "$n")" 0
assert_not "a dry run writes no manifest file, nor their folder" test -e "$T/manifests"
for a in "${APPS[@]}"; do assert "dry run names the $a manifest form it would write" has "$OUT" "DRY-RUN: write $T/manifests/$a.manifest.json"; done
assert_not "the dry run records no App id" grep -q '_APP_ID=[0-9]' "$CFGP"
# OWNER_NAME lands in single-quoted shell and PowerShell strings in the starter,
# so an apostrophe is refused (config loader and substitute.py both).
CFGQ="$T/fleet-apostrophe.env"; new_config "$CFGQ" paid; sed -i "s/^OWNER_NAME=.*/OWNER_NAME=O'Brien/" "$CFGQ"
run bash "$B/create-apps.sh" --config "$CFGQ" --dry-run --out "$T/manifests-q"; rc=$?
assert_eq "an OWNER_NAME with an apostrophe is refused" "$rc" 1
assert "the refusal names OWNER_NAME and the apostrophe" has "$ERR" "invalid value for OWNER_NAME"
assert "the refusal says no apostrophe" has "$ERR" "no apostrophe"
mkdir -p "$T/subst-q"; echo "Example Adopter" > "$T/subst-q/a.txt"
run python3 -I "$B/lib/substitute.py" "$T/subst-q" --owner "$O" --name "O'Brien"; rc=$?
assert_eq "substitute.py refuses a name with an apostrophe" "$rc" 1
assert "substitute.py says why" has "$ERR" "no apostrophe"
printf 'not a code!\n' | run bash "$B/create-apps.sh" --config "$CFGP" --out "$T/manifests" roster; rc=$?
assert_eq "a malformed code is refused" "$rc" 1
printf 'http://127.0.0.1/?code=abc&state=0000\n' | run bash "$B/create-apps.sh" --config "$CFGP" --out "$T/manifests" roster; rc=$?
assert_eq "a redirect URL from another run's form is refused" "$rc" 1
assert "the state mismatch is named" has "$ERR" "does not match this run's manifest"

printf 'code%s\n' 1 2 3 4 5 6 | run bash "$B/create-apps.sh" --config "$CFGP" --out "$T/manifests"; rc=$?
assert_eq "create-apps exits 0" "$rc" 0
assert_eq "six Apps were converted" "$(jqs '.apps | length')" 6
for a in "${APPS[@]}"; do assert "the run writes the $a manifest form" test -f "$T/manifests/$a.html"; done
assert_eq "a fleet-wide App is public when there are two owners" "$(jq -r .public "$T/manifests/guidance-sync.manifest.json")" true
assert_eq "an App on one owner's repos stays private" "$(jq -r .public "$T/manifests/registry-read.manifest.json")" false
assert_eq "settings-admin has the owner's permissions" "$(jq -c .default_permissions "$T/manifests/settings-admin.manifest.json")" \
  '{"administration":"write","actions":"write","issues":"write","metadata":"read"}'
assert_eq "the manifest redirects to this machine, not a third-party host" "$(jq -r .redirect_url "$T/manifests/guidance-sync.manifest.json")" "http://127.0.0.1/"
assert "the form escapes the manifest into an attribute" grep -q 'name="manifest" value="{&quot;name&quot;' "$T/manifests/guidance-sync.html"
for k in GUIDANCE_SYNC SETTINGS_ADMIN SETTINGS_READ EVAL_IMPROVE ROSTER_WRITER REGISTRY_READ; do
  assert "fleet.env records ${k}_APP_ID" grep -qE "^${k}_APP_ID=9000[0-9]{2}$" "$CFGP"
done
assert_eq "guidance-sync's client id is a variable in _agent-guidance" "$(jqs '.values["acme-example/_agent-guidance||variable"].APP_CLIENT_ID')" Iv23liExample1
assert_eq "guidance-sync's key is a repository secret, stored as a hash" "$(jqs '.values["acme-example/_agent-guidance||secret"].APP_PRIVATE_KEY')" "$(sha "${GH_STUB_FAKE_PEM%$'\n'}")"
assert_eq "settings-admin's key is in fleet-apply" "$(jqs '.values["acme-example/repo-settings|fleet-apply|secret"] | keys | join(",")')" REPO_SETTINGS_APP_PRIVATE_KEY
assert_eq "eval-improve's client id is a secret (its gates check both exist)" "$(jqs '.values["acme-example/skills-evals||secret"] | has("EVAL_IMPROVE_APP_CLIENT_ID") and has("EVAL_IMPROVE_APP_PEM")')" true
assert_eq "skills-evals holds the roster and registry-read client ids as variables" \
  "$(jqs '.values["acme-example/skills-evals||variable"] | keys | join(",")')" REGISTRY_READ_APP_CLIENT_ID,ROSTER_APP_CLIENT_ID
assert "it prints each install link" has "$OUT" "https://github.com/apps/acme-example-app-1/installations/new"
assert_not "no client id, key or secret was passed in argv" grep -qE "Iv23liExample|$PEM_MARK|$CS_MARK" "$GH_LOG"
n=$(log_lines "$GH_LOG")
run bash "$B/create-apps.sh" --config "$CFGP" --out "$T/manifests" </dev/null; rc=$?
assert_eq "create-apps second run exits 0" "$rc" 0
assert_eq "create-apps second run makes no write calls" "$(since "$n")" 0
assert "create-apps second run says each App exists" has "$OUT" "roster already created"
jqset 'del(.values["acme-example/skills-evals||variable"].ROSTER_APP_CLIENT_ID)'
run bash "$B/create-apps.sh" --config "$CFGP" --out "$T/manifests" roster </dev/null
assert "a missing client id is reported with the command that fixes it" has "$ERR" "variable ROSTER_APP_CLIENT_ID is missing from acme-example/skills-evals"
jqset '.values["acme-example/skills-evals||variable"].ROSTER_APP_CLIENT_ID = "x"'

run bash "$B/create-environments.sh" --config "$CFGP"; rc=$?
assert_eq "create-environments after the Apps exits 0" "$rc" 0
gs=$(sed -n 's/^GUIDANCE_SYNC_APP_ID=//p' "$CFGP"); rw=$(sed -n 's/^ROSTER_WRITER_APP_ID=//p' "$CFGP")
assert_eq "repo-settings' GUIDANCE_SYNC_APP_ID is the App id" "$(jqs '.values["acme-example/repo-settings||variable"].GUIDANCE_SYNC_APP_ID')" "$gs"
assert_eq "repo-settings' ROSTER_WRITER_APP_ID is the App id" "$(jqs '.values["acme-example/repo-settings||variable"].ROSTER_WRITER_APP_ID')" "$rw"
assert "the count includes values set through stdin" has "$OUT" "Done: 2 change(s)"
# The optional federation ids eval.yml's token exchange reads.
run bash "$B/verify.sh" --config "$CFGP"; rc=$?
assert_not "verify without --only leaves the optional federation ids alone" grep -qF ANTHROPIC_ "$OUT"
run bash "$B/verify.sh" --config "$CFGP" --only federation; rc=$?
assert_eq "verify --only federation fails while fleet.env has no federation ids" "$rc" 1
printf '%s\n' ANTHROPIC_FEDERATION_RULE_ID=fdrl_EXAMPLE0000000001 \
  ANTHROPIC_ORGANIZATION_ID=00000000-0000-4000-8000-000000000001 \
  ANTHROPIC_SERVICE_ACCOUNT_ID=svac_EXAMPLE0000000001 ANTHROPIC_WORKSPACE_ID=wrkspc_EXAMPLE0000000001 >> "$CFGP"
run bash "$B/create-environments.sh" --config "$CFGP"; rc=$?
assert_eq "create-environments with the federation ids exits 0" "$rc" 0
assert_eq "skills-evals holds the four federation ids as variables" \
  "$(jqs '[.values["acme-example/skills-evals||variable"] | keys[] | select(startswith("ANTHROPIC_"))] | join(",")')" \
  ANTHROPIC_FEDERATION_RULE_ID,ANTHROPIC_ORGANIZATION_ID,ANTHROPIC_SERVICE_ACCOUNT_ID,ANTHROPIC_WORKSPACE_ID
assert_eq "the workspace id is the fleet.env value" "$(jqs '.values["acme-example/skills-evals||variable"].ANTHROPIC_WORKSPACE_ID')" wrkspc_EXAMPLE0000000001
run bash "$B/verify.sh" --config "$CFGP" --only federation; rc=$?
assert_eq "verify --only federation passes once they are set" "$rc" 0
