# ======================================================== copy-starter.sh
# Each fleet repo gets a bare remote holding the README create-repos.sh wrote.
for r in "${FLEET[@]}"; do
  g="$T/remotes/$O/$r.git"; git init -q --bare "$g"
  w="$T/tmp/init-$r"; git init -q "$w"
  bash -c '. "$1/lib/common.sh"; generated_readme "$2"' _ "$B" "$r" > "$w/README.md"
  git -C "$w" add -A && git -C "$w" commit -qm init && git -C "$w" push -q "$g" HEAD:main; rm -rf "$w"
done
tree_of() { bash -c '. "$1/lib/common.sh"; kit_tree "$2"' _ "$B" "$1"; }
merge() { # repo branch: what merging its pull request does (a fast-forward of main)
  local g="$T/remotes/$O/$1.git"
  git --git-dir="$g" merge-base --is-ancestor main "refs/heads/$2" && git --git-dir="$g" update-ref refs/heads/main "refs/heads/$2"
}
on_main() { git --git-dir="$T/remotes/$O/$1.git" show "main:$2"; }

CFG1="$T/fleet-one.env"; new_config "$CFG1" paid; sed -i '/^OWNER_TWO=/d' "$CFG1"
