: > "$FAKE_ENGINE_LOG"
run bash "$B/apply-settings.sh" --config "$CFGF"; rc=$?
assert_eq "a declared repo that does not exist stops the apply" "$rc" 1
assert "the missing repo is named" has "$ERR" "MISSING: fleet.yml declares acme-fake/two"
assert_eq "the engine never ran" "$(log_lines "$FAKE_ENGINE_LOG")" 0
gh repo create "$F/two" --private >/dev/null
sed '/_APP_ID=/d' "$CFGF" > "$T/fleet-noids.env"
run bash "$B/apply-settings.sh" --config "$T/fleet-noids.env"; rc=$?
assert_eq "apply-settings refuses without the bypass App ids" "$rc" 1
assert "the missing ids are named" has "$ERR" "GUIDANCE_SYNC_APP_ID ROSTER_WRITER_APP_ID empty in fleet.env"
run bash "$B/apply-settings.sh" --config "$CFGF" --owner someone-else; rc=$?
assert_eq "--owner must be one of fleet.env's owners" "$rc" 1
run bash "$B/apply-settings.sh" --config "$CFGF" --owner acme-fake-two --dry-run; rc=$?
assert_eq "--owner OWNER_TWO previews that owner's repos" "$rc" 0
assert "the second owner's repos are checked" has "$OUT" "declares 1 repo(s) of acme-fake-two"
# The real engine takes every flag apply-settings.sh passes it.
ENG="$K/starter/repo-settings/scripts/repo_settings.py"
for f in --config --owner --dry-run --cms-label-only; do
  assert "the exported engine's apply takes $f" bash -c 'python3 -I "$1" apply --help | grep -qF -- "$2"' _ "$ENG" "$f"
done
for f in --config --owner; do
  assert "the exported engine's diff takes $f" bash -c 'python3 -I "$1" diff --help | grep -qF -- "$2"' _ "$ENG" "$f"
done
assert "the exported engine skips label-only repos by that name" bash -c 'python3 -I "$1" apply --help | grep -qF "{skip,only}"' _ "$ENG"

# ======================================================== install-machine.sh
# Fake installers that log how they were called.
export INSTALL_LOG="$T/install.log"; : > "$INSTALL_LOG"
fake_installer() { printf '#!/usr/bin/env bash\nprintf "%%s %%s\\n" "%s" "$*" >> "$INSTALL_LOG"\n' "$1"; }
w="$T/tmp/fake-as"; mkdir -p "$w/scripts"
fake_installer setup.sh > "$w/setup.sh"; fake_installer install-agent-hooks.sh > "$w/scripts/install-agent-hooks.sh"
git init -q "$w" && git -C "$w" add -A && git -C "$w" commit -qm fake
git init -q --bare "$T/remotes/$F/acsi-agentskills.git" && git -C "$w" push -q "$T/remotes/$F/acsi-agentskills.git" HEAD:main; rm -rf "$w"
w="$T/tmp/fake-ag"; mkdir -p "$w/scripts" "$w/.claude/hooks"
fake_installer register-memory-home-hook.sh > "$w/scripts/register-memory-home-hook.sh"
fake_installer register-codex-hook.sh > "$w/scripts/register-codex-hook.sh"
printf '#!/usr/bin/env bash\n' > "$w/.claude/hooks/memory-home.sh"
git init -q "$w" && git -C "$w" add -A && git -C "$w" commit -qm fake
git init -q --bare "$T/remotes/$F/_agent-guidance.git" && git -C "$w" push -q "$T/remotes/$F/_agent-guidance.git" HEAD:main; rm -rf "$w"
RD="$T/home/repos"
run bash "$B/install-machine.sh" --config "$CFGF" --dry-run; rc=$?
assert_eq "install-machine dry run exits 0" "$rc" 0
assert_eq "the dry run runs no installer" "$(log_lines "$INSTALL_LOG")" 0
assert_not "the dry run clones nothing into REPOS_DIR" test -e "$RD"
assert "the dry run names the final hook path" has "$OUT" "--hook $RD/_agent-guidance/.claude/hooks/memory-home.sh"
run bash "$B/install-machine.sh" --config "$CFGF"; rc=$?
assert_eq "install-machine exits 0" "$rc" 0
assert_eq "it runs the repos' own installers, in order, with their arguments" "$(cat "$INSTALL_LOG")" \
  "$(printf '%s\n' "setup.sh --owner-machine" "install-agent-hooks.sh " "register-memory-home-hook.sh --hook $RD/_agent-guidance/.claude/hooks/memory-home.sh")"
assert "it cloned acsi-agentskills into REPOS_DIR" test -f "$RD/acsi-agentskills/setup.sh"
: > "$INSTALL_LOG"
run bash "$B/install-machine.sh" --config "$CFGF" --with-codex; rc=$?
assert_eq "a second install-machine run exits 0" "$rc" 0
assert "a current clone is left as it is" has "$OUT" "$RD/acsi-agentskills is current"
assert "--with-codex without ~/.codex skips the Codex hook" has "$OUT" "there is no ~/.codex"
mkdir -p "$HOME/.codex"; : > "$INSTALL_LOG"
run bash "$B/install-machine.sh" --config "$CFGF" --with-codex; rc=$?
assert "--with-codex with ~/.codex registers the Codex hook" grep -q '^register-codex-hook.sh' "$INSTALL_LOG"
w="$T/tmp/push-as"; git clone -q "$BOOTSTRAP_GIT_BASE/$F/acsi-agentskills.git" "$w"
printf '# v2\n' >> "$w/setup.sh"; git -C "$w" commit -qam v2 && git -C "$w" push -q origin HEAD:main; rm -rf "$w"
before=$(git -C "$RD/acsi-agentskills" rev-parse HEAD)
fetch_head_before=$(cat "$RD/acsi-agentskills/.git/FETCH_HEAD" 2>/dev/null | md5sum)
run bash "$B/install-machine.sh" --config "$CFGF" --dry-run; rc=$?
assert_eq "an install-machine dry run over existing clones exits 0" "$rc" 0
assert "the dry run says it would fetch" has "$OUT" "DRY-RUN: git -C $RD/acsi-agentskills fetch --quiet origin main"
assert_eq "the dry run does not fetch (FETCH_HEAD unchanged)" "$(cat "$RD/acsi-agentskills/.git/FETCH_HEAD" 2>/dev/null | md5sum)" "$fetch_head_before"
assert_eq "the dry run does not move the clone" "$(git -C "$RD/acsi-agentskills" rev-parse HEAD)" "$before"
assert_not "the dry run has not fetched the new commit" git -C "$RD/acsi-agentskills" cat-file -e "$(git --git-dir="$T/remotes/$F/acsi-agentskills.git" rev-parse main)"
run bash "$B/install-machine.sh" --config "$CFGF"; rc=$?
assert "a clean clone on its default branch is fast-forwarded" has "$OUT" "fast-forwarded $RD/acsi-agentskills"
git -C "$RD/acsi-agentskills" remote set-url origin "$BOOTSTRAP_GIT_BASE/someone-else/acsi-agentskills.git"
run bash "$B/install-machine.sh" --config "$CFGF"; rc=$?
assert_eq "a clone of another owner's repo is refused" "$rc" 1
assert "the wrong origin is named" has "$ERR" "not acme-fake/acsi-agentskills"

# ======================================================== the checkers, and that each can fail
for c in check-refs.py check-branch-prefixes.py check-one-owner.py; do
  run python3 -I "$B/tests/$c"; rc=$?
  assert_eq "$c passes on the kit" "$rc" 0
done
run python3 -I "$B/tests/check-one-owner.py" --no-collapse; rc=$?
assert_eq "check-one-owner fails when substitute.py does not collapse the second owner" "$rc" 1
assert "the failure is a duplicate key" has "$OUT" "duplicate key 'GH_TOKEN_ACME_SOLO'"
for c in check-steps.py check-guide-lists.py check-links.py; do
  run python3 -I "$B/tests/$c" "$K"; rc=$?
  assert_eq "$c passes on the kit" "$rc" 0
done
run python3 -I "$B/render-quickstart.py" --check; rc=$?
assert_eq "the quick start table matches steps.json" "$rc" 0
# A scratch kit: copies of everything the checkers read, the exports linked.
mk_kit() {
  rm -rf "$T/kit"; mkdir -p "$T/kit"
  cp -a "$K/README.md" "$K/LICENSE" "$K/docs" "$K/bootstrap" "$K/.claude" "$T/kit/"
  ln -s "$K/starter" "$T/kit/starter"; ln -s "$K/export" "$T/kit/export"
  ln -s "$K/run-all-tests.sh" "$T/kit/run-all-tests.sh"
}
kb() { python3 -I "$T/kit/bootstrap/$1" "${@:2}" >"$OUT" 2>&1; }
mk_kit
kb tests/check-links.py "$T/kit"; rc=$?
assert_eq "check-links passes on the unchanged scratch kit" "$rc" 0
kb tests/check-steps.py "$T/kit"; rc=$?
assert_eq "check-steps passes on the unchanged scratch kit" "$rc" 0
printf '\nSee [nowhere](docs/nope.md) and [no anchor](docs/routines.md#no-such-heading).\n' >> "$T/kit/README.md"
kb tests/check-links.py "$T/kit"
assert "check-links fails on a missing file" has "$OUT" "docs/nope.md does not exist"
assert "check-links fails on a missing anchor" has "$OUT" "has no heading #no-such-heading"
mk_kit
jq '.steps[3].link = "docs/settings-and-apps.md#no-such-heading" | .steps[4].phase = 3 | .steps[5].check.groups = ["rulesets"]' \
  "$K/bootstrap/steps.json" > "$T/kit/bootstrap/steps.json"
kb tests/check-steps.py "$T/kit"; rc=$?
assert_eq "check-steps fails on a bad steps.json" "$rc" 1
assert "check-steps names the broken anchor" has "$OUT" "has no heading #no-such-heading"
assert "check-steps names the old guide's field" has "$OUT" "step 4: no fields from the old guide"
assert "check-steps names the unknown verify group" has "$OUT" "verify group 'rulesets'"
kb render-quickstart.py --check; rc=$?
assert_eq "render-quickstart --check fails on a stale table" "$rc" 1
mk_kit
grep -vF '| `wsl-automation` | The Codex Cloud bootstrap pin |' "$K/docs/generated-files.md" > "$T/kit/docs/generated-files.md"
kb tests/check-guide-lists.py "$T/kit"; rc=$?
assert_eq "check-guide-lists fails when a REGENERATE.md item has no step" "$rc" 1
mk_kit
grep -vF '"acsi-agentskills|-|secret|PRIVACY_DENYLIST|file"' "$K/bootstrap/lib/common.sh" > "$T/kit/bootstrap/lib/common.sh"
kb tests/check-refs.py; rc=$?
assert_eq "check-refs fails when a secret a workflow reads has no setter" "$rc" 1
assert "check-refs names the secret" has "$OUT" "PRIVACY_DENYLIST"
mk_kit
sed -i 's/claude\/scaffold-\*/claude\/scaffolding-*/' "$T/kit/docs/evals-and-loop.md"
kb tests/check-branch-prefixes.py; rc=$?
assert_eq "check-branch-prefixes fails when the docs name a lane wrong" "$rc" 1

# ======================================================== secrets never leave the stubs
assert_not "no private key, client secret or bearer is in any file the run wrote" grep -rqF -e "$PEM_MARK" -e "$CS_MARK" -e "$BEARER" "$T" --exclude-dir=kit
assert_not "fleet.env holds no secret" grep -qiE 'pem|secret|bearer|denylist' "$CFGP"

printf '%d assertions passed, %d failed\n' "$PASSES" "$FAILS"
[ "$FAILS" = 0 ]
